26	// mustQueryPoints 要求 query_points 查询成功并返回明细结果。
27	func mustQueryPoints(t *testing.T, store *MetricStore, line string) *QueryPointsResult {
28		t.Helper()
29		res, err := store.QueryPointsLine(line)
30		if err != nil {
31			t.Fatalf("expected query_points success for %s, got error: %+v", line, err)
32		}
33		return res
34	}
