46	// queryPointsAll 构造省略 labels 的 query_points 对象文本。
47	func queryPointsAll(name string, start, end int64) string {
48		return fmt.Sprintf(`{"op":"query_points","name":%s,"start":%d,"end":%d}`,
49			jsonString(name), start, end)
50	}
