105	// TestQueryPointsResultShape 锁定成功结果的 JSON 形状：op 为 query_points，
106	// 序列条目只有 name、labels、points（没有 count/average），点只有
107	// timestamp 与 value；无命中时 series 是空数组而不是 null。
108	func TestQueryPointsResultShape(t *testing.T) {
109		store := NewMetricStore()
110		mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
111	
112		res := mustQueryPoints(t, store, queryPointsAll("cpu", 0, 2000))
113		raw := marshalCompact(t, res)
114		want := `{"status":"ok","op":"query_points","series":[` +
115			`{"name":"cpu","labels":{"host":"a"},"points":[{"timestamp":1000,"value":2}]}]}`
116		if raw != want {
117			t.Fatalf("query_points JSON = %s, want %s", raw, want)
118		}
119		// 序列化后的条目不得携带均值查询的统计字段。
120		var decoded map[string]any
121		if err := json.Unmarshal([]byte(raw), &decoded); err != nil {
122			t.Fatal(err)
123		}
124		entry := decoded["series"].([]any)[0].(map[string]any)
125		for _, banned := range []string{"count", "average"} {
126			if _, ok := entry[banned]; ok {
127				t.Fatalf("query_points entry must not carry %q: %v", banned, entry)
128			}
129		}
130	
131		// 无命中：成功的空 series 数组。
132		res = mustQueryPoints(t, store, queryPointsAll("cpu", 2000, 3000))
133		if res.Series == nil || len(res.Series) != 0 {
134			t.Fatalf("miss query_points = %+v, want non-nil empty series list", res.Series)
135		}
136		if raw = marshalCompact(t, res); raw != `{"status":"ok","op":"query_points","series":[]}` {
137			t.Fatalf("empty query_points JSON = %s, want empty series array", raw)
138		}
139	}
